 const reg=region();if(!reg.outposts.includes(room.sector)){reg.outposts.push(room.sector);reg.outposts.sort((a,b)=>a-b);msg('📡 BALISE DU SECTEUR '+(room.sector+1)+' ACTIVÉE !')}else msg('Balise déjà activée.');
