const WEAPON_SPRITES = {"pistol_used":"","pistol_rescue":"","pistol_reinforced":"","smg_sector":"","vektor":"","carbine_k17":"","spectre":"","ion":"","cendre":"","rifle_recovery":"","rifle_industrial":"","nomade9":"","precision":"","impulse":"","prototype":"","reliquat":""};
