function itemRow(w,i,source){return uiWeaponCard(w,i,source,false)}
function uniqueCheck(){let seen=new Set(),items=[data.equipped,...data.stash];if(data.run)items=[data.run.equipped,...data.run.bag];for(let w of items){if(!w)continue;if(seen.has(w.id))return false;seen.add(w.id)}return true}
function equipHome(i){let w=data.stash[i];if(!w)return;let old=data.equipped;data.stash.splice(i,1);data.equipped=w;if(old)data.stash.push(old);data.insured=null;persist();render();msg(`${w.name} équipé. Assurance à renouveler.`)}
function equipBag(i){let r=data.run,w=r.bag[i];if(!w)return;let old=r.equipped;r.bag.splice(i,1);r.equipped=w;if(old){r.bag.push(old)}if(!uniqueCheck())msg('Erreur d’inventaire détectée.');else msg(`${w.name} équipé. Assurance non transférée.`);persist();render();openOverlay('bag')}
function drop(i){let r=data.run,w=r.bag[i];if(!w)return;if(w.id===r.insuredId&&!confirm('Abandonner cet objet annulera son assurance. Confirmer ?'))return;if(w.id===r.insuredId)r.insuredId=null;r.bag.splice(i,1);persist();render();openOverlay('bag');msg(`${w.name} abandonné.`)}
function sell(i){if(data.run)return;let w=data.stash[i];if(!w)return;if(w.id===data.insured){msg("Objet assuré : vente refusée.");return}let gain=salvagePrice(w);if(!confirm(`Vendre définitivement ${w.name} pour ${gain} crédits ?`))return;data.stash.splice(i,1);data.credits+=gain;persist();render();msg(`${w.name} vendu : +${gain} crédits.`)}
// Marchand évolutif — stock sauvegardé, jamais régénéré sur simple ouverture.
const MERCHANT_CATALOG=[
 {name:'Pistolet de secours',rar:'Commun',dmg:17,rate:2.1},
 {name:'Pistolet renforcé',rar:'Commun',dmg:21,rate:2},
 {name:'Fusil de récupération',rar:'Inhabituel',dmg:26,rate:1.5},
 {name:'Carabine K-17',rar:'Inhabituel',dmg:23,rate:2.2},
 {name:'Viseur de précision',rar:'Rare',dmg:35,rate:1.15},
 {name:'SMG de secteur',rar:'Rare',dmg:18,rate:3.8},
 {name:'Fusil industriel',rar:'Rare',dmg:32,rate:1.75},
 {name:'Lanceur à impulsion',rar:'Épique',dmg:44,rate:1.3},
 {name:'Prototype balistique',rar:'Épique',dmg:29,rate:2.8},
 {name:'Reliquat de citadelle',rar:'Légendaire',dmg:48,rate:2.2}
];
const MERCHANT_RANK={Commun:0,Inhabituel:1,Rare:2,'Épique':3,'Légendaire':4,Mythique:5};
function merchantTier(){let reg=region();return Math.min(4,Math.max(0,Number(reg.maxSector)||0)+(reg.bossDefeated?1:0))}
function merchantPrice(w){let rk=MERCHANT_RANK[w.rar]||0;return Math.max(100,Math.round((Number(w.dmg)*10+Number(w.rate)*60)*(1+rk*.58)/10)*10)}
function ensureMerchant(){
 if(!data.merchant||!Array.isArray(data.merchant.stock))data.merchant={stock:[],cycle:0,lastRefreshRun:data.runs,highestTier:merchantTier()};
 const m=data.merchant, tier=merchantTier();
 if(!m.stock.length||data.runs-m.lastRefreshRun>=2||tier>m.highestTier){
  const pool=MERCHANT_CATALOG.filter(w=>(MERCHANT_RANK[w.rar]||0)<=Math.min(4,1+tier));
  // Deterministic rotation by cycle avoids rerolling offers by closing the menu.
  const selected=[];
  for(let i=0;i<7;i++){
    const entry=pool[(i*3+m.cycle*2+Math.floor(i/3))%pool.length];
    selected.push({...entry,offerId:'offer-'+m.cycle+'-'+i,price:merchantPrice(entry),sold:false});
  }
  m.stock=selected;m.lastRefreshRun=data.runs;m.highestTier=tier;m.cycle++;
 }
 return m;
}
let merchantTab='buy', merchantFilter='all', merchantSort='recommended';
function merchantOpen(tab='buy'){
 if(data.run){msg('Retourne au refuge pour commercer.');return}
 merchantTab=tab;ensureMerchant();merchantRender();
}
function merchantScore(w){return (Number(w.dmg)||0)*(Number(w.rate)||0)}
function merchantRender(){
 const m=ensureMerchant(),stock=m.stock||[],remaining=stock.filter(w=>!w.sold).length;
 const until=Math.max(0,2-(data.runs-m.lastRefreshRun));
 const hint=until===0?'Un nouvel arrivage sera disponible à la prochaine visite du comptoir.':`Prochain arrivage : ${until} expédition${until>1?'s':''} terminée${until>1?'s':''}, ou nouvelle avancée dans K-17.`;
 const mirror=$('merchantRefreshHint');if(mirror)mirror.textContent=hint;
 if($('merchantCreditsMirror'))$('merchantCreditsMirror').textContent=data.credits;
 if($('merchantReserveCount'))$('merchantReserveCount').textContent=data.stash.length;
 if($('merchantOffersCount'))$('merchantOffersCount').textContent=remaining;
 let html=`<div class="merchant-shop ash-commerce"><div class="merchant-tabs ash-commerce-tabs" role="group" aria-label="Opérations du marchand"><button type="button" data-merchant-tab="buy" aria-pressed="${merchantTab==='buy'}" class="${merchantTab==='buy'?'active':''}">${afIcon("merchant")} Acheter</button><button type="button" data-merchant-tab="sell" aria-pressed="${merchantTab==='sell'}" class="${merchantTab==='sell'?'active':''}">${afIcon("credits")} Vendre</button></div>`;
 if(merchantTab==='buy'){
  const current=data.equipped,base=merchantScore(current||{});
  const filters=[['all','Toutes'],['available','Achetables'],['upgrade','Plus puissantes']];
  html+=`<div class="ash-commerce-toolbar"><div class="ash-commerce-filters" role="group" aria-label="Filtrer les armes">${filters.map(([id,label])=>`<button type="button" class="${merchantFilter===id?'selected':''}" data-merchant-filter="${id}" aria-pressed="${merchantFilter===id}">${label}</button>`).join('')}</div><label class="ash-merchant-sort">TRIER <select id="merchantSort" aria-label="Trier les offres"><option value="recommended" ${merchantSort==='recommended'?'selected':''}>Disponibilité</option><option value="price" ${merchantSort==='price'?'selected':''}>Prix croissant</option><option value="power" ${merchantSort==='power'?'selected':''}>Puissance théorique</option></select></label></div>`;
  // Group identical lots for readability without changing stock quantities or economy.
  const grouped=new Map();
  stock.forEach((w,i)=>{
   const k=[w.name,w.rar,w.dmg,w.rate,w.price].join('|');
   if(!grouped.has(k))grouped.set(k,{w,i,total:0,remaining:0});
   const g=grouped.get(k);g.total++;
   if(!w.sold){if(g.remaining===0){g.w=w;g.i=i;}g.remaining++;}
  });
  let offers=[...grouped.values()];
  if(merchantFilter==='available')offers=offers.filter(g=>g.remaining>0&&data.credits>=g.w.price);
  else if(merchantFilter==='upgrade')offers=offers.filter(g=>g.remaining>0&&merchantScore(g.w)>base);
  offers.sort((a,b)=>{
   if(merchantSort==='price')return a.w.price-b.w.price||a.i-b.i;
   if(merchantSort==='power')return merchantScore(b.w)-merchantScore(a.w)||a.i-b.i;
   return Number(a.remaining===0)-Number(b.remaining===0)||Number(data.credits<b.w.price)-Number(data.credits<a.w.price)||a.i-b.i;
  });
  html+=`<p class="ash-merchant-explainer">${remaining} offre${remaining!==1?'s':''} disponible${remaining!==1?'s':''} · Les crédits sont dépensés seulement après confirmation. <span>Puissance = dégâts × cadence (estimation hors bonus).</span></p>`;
  html+='<div class="ash-offer-list">';
  html+=offers.map(({w,i,remaining:copies,total})=>{
   const sold=copies===0,power=merchantScore(w),delta=Math.round((power-base)*10)/10,ok=power>base,affordable=data.credits>=w.price;
   return `<article class="ui-weapon merchant-offer ash-merchant-offer ${sold?'ash-offer-sold':''}" style="--item-rarity:${tint(w)}"><div class="ash-merchant-offer-head"><span class="ash-offer-picture">${weaponArt(w)}</span><div class="ash-offer-copy"><span class="rarity">${uiSafe(w.rar)}</span><b>${uiSafe(w.name)}</b><span class="ash-offer-traits">${afIcon("damage")} ${Number(w.dmg)} DGT <span aria-hidden="true">·</span> ${afIcon("rate")} ${Number(w.rate)} tirs/s</span><span class="ash-offer-stock">${copies?copies+" en stock": "Épuisé"}${total>1?" · lot de "+total:""}</span></div><span class="ash-price-chip">${w.price} ¤</span></div><div class="ash-offer-comparison"><span>Puissance théorique : <strong>${power.toFixed(1)}</strong></span><span class="${ok?'ui-up':delta<0?'ui-down':''}">${base?((delta>0?'+':'')+delta.toFixed(1)+' vs équipée'):'Sans comparaison'}</span></div><button type="button" data-merchant-buy="${i}" ${sold||!affordable?'disabled':''}>${sold?'DÉJÀ VENDUE':!affordable?'IL MANQUE '+(w.price-data.credits)+' ¤':'ACHETER · '+w.price+' ¤'}</button></article>`;
  }).join('');
  if(!offers.length)html+='<div class="ash-merchant-empty">Aucune arme pour ce filtre. Essaie « Toutes » ou reviens après un nouvel arrivage.</div>';
  html+='</div>';
 }else{
  html+='<div class="ash-merchant-explainer">Les ventes sont définitives. Le prix de rachat est inférieur au prix marchand ; une arme achetée est reprise au maximum à 25 % de son coût. Ton arme équipée ne figure pas dans la réserve.</div>';
  const items=data.stash.map((w,i)=>({w,i})).sort((a,b)=>salvagePrice(b.w)-salvagePrice(a.w)||a.i-b.i);
  html+='<div class="ash-offer-list">';
  html+=items.map(({w,i})=>{
   const locked=w.id===data.insured;
   return `<article class="ui-weapon merchant-offer ash-merchant-offer" style="--item-rarity:${tint(w)}"><div class="ash-merchant-offer-head"><span class="ash-offer-picture">${weaponArt(w)}</span><div class="ash-offer-copy"><span class="rarity">${uiSafe(w.rar)}</span><b>${uiSafe(w.name)}</b><span class="ash-offer-traits">${afIcon("damage")} ${Number(w.dmg)||0} DGT · ${afIcon("rate")} ${Number(w.rate)||0} tirs/s</span></div><span class="ash-price-chip">+${salvagePrice(w)} ¤</span></div><button type="button" data-merchant-sell="${i}" ${locked?'disabled':''}>${locked?'OBJET ASSURÉ — VENTE BLOQUÉE':'VENDRE · +'+salvagePrice(w)+' ¤'}</button></article>`;
  }).join('');
  if(!items.length)html+='<div class="ash-merchant-empty">Réserve vide. Rapporte des armes lors d’une extraction pour pouvoir les revendre.</div>';
  html+='</div>';
 }
 html+=`<div class="ash-trader-footnote"><b>COMMENT FONCTIONNE LE COMPTOIR ?</b><p>Le stock change après deux expéditions terminées ou une nouvelle progression de secteur. Les armes plus rares apparaissent au fil de l'exploration. Les achats restent dans la réserve jusqu'à leur équipement.</p></div></div>`;
 const host=$('merchantPageContent');if(host)host.innerHTML=html;
 else tool('¤ LE COMPTOIR — MARCHAND',html);
}
let selectedInventoryId=null;
let inventoryPage=0;
let inventorySortMode="default";
let inventoryRarity="all";
let inventoryQuery="";
const INVENTORY_PAGE_SIZE=20;
function renderInventorySelection(){
 const host=$('inventorySelection');if(!host)return;
 const i=data.stash.findIndex(w=>w.id===selectedInventoryId);
 if(i<0){host.hidden=true;host.innerHTML='';return;}
 const w=data.stash[i];host.hidden=false;
 host.innerHTML=`<div class="ash-loot-selection-heading"><span class="inventory-detail-label">ARME SÉLECTIONNÉE</span>${lootRarityBadge(w)}</div>
 <div class="inventory-selected-head"><span class="inventory-selected-art">${weaponArt(w)}</span><div class="ash-loot-selected-copy"><b>${uiSafe(w.name)}</b><small>${lootDisplay(w.dmg)} dégâts · ${lootDisplay(w.rate)} tirs/s</small><strong>${lootDisplay(lootPower(w))} puissance indicative</strong></div></div>
 ${lootCompare(w,data.equipped)}
 <div class="ash-loot-resale">Valeur de revente : <strong>${salvagePrice(w)} crédits</strong></div>
 <div class="inventory-selected-actions"><button type="button" data-grid-equip="${i}">ÉQUIPER</button><button type="button" data-grid-sell="${i}" class="ui-secondary">VENDRE · ${salvagePrice(w)} CRÉDITS</button></div>`;
}
function renderRefugeCharacter(){
 const stats=data.stats||{};
 if($('activeWeaponArt'))$('activeWeaponArt').innerHTML=weaponArt(data.equipped);
 if($('characterEquippedSlotArt'))$('characterEquippedSlotArt').innerHTML=weaponArt(data.equipped);
 if($('characterHeldWeaponImage')){
  const weaponName=String(data.equipped?.name||'').toLowerCase();
  const isPistol=/pistolet|secours/.test(weaponName)||!data.equipped;
  const img=$('characterHeldWeaponImage');
  const source=isPistol?img.dataset.pistolSrc:$('nomadeRifleData')?.src;
  if(source && img.src!==source) img.src=source;
}
 // Accueil : résumé dynamique de l'équipement, lecture seule.
 if($('homeWeaponArt'))$('homeWeaponArt').innerHTML=weaponArt(data.equipped);
 if($('homeWeaponName'))$('homeWeaponName').textContent=data.equipped?.name||'Aucune arme';
 if($('homeWeaponMeta'))$('homeWeaponMeta').textContent=data.equipped?`${data.equipped.rar} · ${data.equipped.dmg+data.dmgLv*3} DGT · ${data.equipped.rate} tirs/s`:'Équipement à préparer';
 if($('homeInsuranceState'))$('homeInsuranceState').textContent=data.equipped&&data.insured===data.equipped.id?'◆ Arme assurée':'Sans assurance';
 if($('homeStashState'))$('homeStashState').textContent=`Réserve : ${data.stash.length}`;
 if($('characterWeaponBadge'))$('characterWeaponBadge').textContent=data.equipped?`${data.equipped.rar} · ${data.equipped.name}`:'Aucune arme';
 if($('characterPowerBadge'))$('characterPowerBadge').textContent=data.equipped?`${data.equipped.dmg+data.dmgLv*3} DGT · ${data.equipped.rate} tirs/s`:'Puissance nulle';
 if($('characterInsuranceBadge'))$('characterInsuranceBadge').textContent=data.insured===data.equipped?.id?'Objet assuré':'Sans assurance';
 if($('charExtractions'))$('charExtractions').textContent=stats.extractions||0;
 if($('charDeaths'))$('charDeaths').textContent=stats.deaths||0;
 if($('charStashCount'))$('charStashCount').textContent=data.stash.length;
 if($('charRunCount'))$('charRunCount').textContent=data.runs;
 if($('loadoutWeaponName'))$('loadoutWeaponName').textContent=data.equipped?data.equipped.name:'Aucune';
 if($('loadoutWeaponStats'))$('loadoutWeaponStats').textContent=data.equipped?`${data.equipped.rar} · ${data.equipped.dmg} dégâts · ${data.equipped.rate} tirs/s`:'Pas d’arme équipée';
 if($('loadoutInsuranceState'))$('loadoutInsuranceState').textContent=data.insured===data.equipped?.id?'Active':'Inactive';
 if($('loadoutInsuranceHint'))$('loadoutInsuranceHint').textContent=data.insured===data.equipped?.id?'Objet protégé pour la prochaine sortie':`Prime : ${premium()} ¤`;
 if($('loadoutHpLevel'))$('loadoutHpLevel').textContent=`Niveau ${data.hpLv}`;
 if($('loadoutHpBonus'))$('loadoutHpBonus').textContent=`+${data.hpLv*15} PV permanents`;
 if($('loadoutDmgLevel'))$('loadoutDmgLevel').textContent=`Niveau ${data.dmgLv}`;
 if($('loadoutDmgBonus'))$('loadoutDmgBonus').textContent=`+${data.dmgLv*3} dégâts permanents`;
 if($('inventoryEquippedLabel'))$('inventoryEquippedLabel').textContent=data.equipped?`${data.equipped.name} · ${data.equipped.rar}`:'Aucune arme';
 const preview=$('characterReservePreview');
 if(preview){
  const ranked=data.stash.map((w,i)=>({w,i})).filter(({w})=>{
   const rar=inventoryRarity==='all'||w.rar===inventoryRarity;
   const normalize=t=>String(t||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('fr-FR');
   return rar&&(!inventoryQuery||normalize(w.name+' '+w.rar).includes(normalize(inventoryQuery)));
  });
  const sortable={rarity:w=>LOOT_RARITY_RANK[w.rar]||0,power:w=>lootPower(w),damage:w=>lootNumber(w.dmg),rate:w=>lootNumber(w.rate),value:w=>salvagePrice(w)};
  if(sortable[inventorySortMode])ranked.sort((a,b)=>sortable[inventorySortMode](b.w)-sortable[inventorySortMode](a.w)||a.i-b.i);
  const pages=Math.max(1,Math.ceil(ranked.length/INVENTORY_PAGE_SIZE));
  inventoryPage=Math.max(0,Math.min(inventoryPage,pages-1));
  const offset=inventoryPage*INVENTORY_PAGE_SIZE,items=ranked.slice(offset,offset+INVENTORY_PAGE_SIZE);
  const selectedVisible=ranked.some(({w})=>w.id===selectedInventoryId);
  if(!selectedVisible)selectedInventoryId=ranked.length?ranked[0].w.id:null;
  const summary=$('ashLootInventoryCount');if(summary)summary.textContent=`${ranked.length} / ${data.stash.length} armes affichées`;
  document.querySelectorAll('[data-loot-rarity]').forEach(b=>{const active=b.dataset.lootRarity===inventoryRarity;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));});
  const cards=items.map(({w,i})=>`<button type="button" class="inventory-cell ash-loot-inventory-cell ${w.id===selectedInventoryId?'inventory-active':''}" data-inventory-index="${i}" aria-pressed="${w.id===selectedInventoryId}" aria-label="Voir ${uiSafe(w.name)} : ${uiSafe(w.rar)}, puissance ${lootDisplay(lootPower(w))}" style="--item-rarity:${tint(w)}"><span class="inventory-symbol">${weaponArt(w)}</span><span class="inventory-name">${uiSafe(w.name)}</span><span class="inventory-rarity">${uiSafe(w.rar)}</span><span class="ash-loot-cell-power">${lootDisplay(lootPower(w))} PUISS.</span></button>`).join('');
  preview.innerHTML=ranked.length?cards+Array.from({length:Math.max(0,Math.min(8-items.length,8))},()=>'<span class="inventory-cell inventory-empty" aria-hidden="true"></span>').join(''):'<div class="ash-loot-no-results">Aucune arme ne correspond aux filtres. <button type="button" data-loot-reset>Réinitialiser</button></div>';
  const controls=$('inventoryPages');if(controls){controls.hidden=pages<=1;controls.innerHTML=pages>1?`<button type="button" data-inventory-page="prev" ${inventoryPage===0?'disabled':''}>← Précédent</button><span>${inventoryPage+1} / ${pages} · ${ranked.length} armes</span><button type="button" data-inventory-page="next" ${inventoryPage===pages-1?'disabled':''}>Suivant →</button>`:'';}
  renderInventorySelection();
 }

}
function renderRefugeProgress(){
 const reg=region(), max=Math.min(3,Math.max(0,Number(reg.maxSector)||0));
 const visitedCount=max+1;
 if($('progressSectorCount'))$('progressSectorCount').textContent=`${visitedCount}/4`;
 if($('progressOutpostCount'))$('progressOutpostCount').textContent=`${reg.outposts.length}/3`;
 if($('progressBossState'))$('progressBossState').textContent=reg.bossDefeated?'Vaincu':'À affronter';
 const names=['PÉRIPHÉRIE','LABORATOIRES','FONDERIE','CITADELLE'];
 let goalTitle,goalText,goalBadge;
 if(reg.bossDefeated){goalTitle='Gardien vaincu · K-17 parcouru';goalText='Continue à améliorer ton arsenal et tes performances. Helix est débloquée pour une version future, non jouable ici.';goalBadge='ACCOMPLI';}
 else if(max<3){goalTitle=`Atteindre : ${names[max+1]}`;goalText=`Explore de nouvelles salles pour découvrir le secteur ${max+2}. Les secteurs découverts enrichissent progressivement le stock du Marchand.`;goalBadge='EXPLORATION';}
 else {goalTitle='Trouver le Gardien de K-17';goalText='La Citadelle est découverte. Poursuis l’exploration et prépare une arme adaptée pour affronter le Gardien.';goalBadge='OBJECTIF FINAL';}
 if($('sectorGoalTitle'))$('sectorGoalTitle').textContent=goalTitle;
 if($('sectorGoalText'))$('sectorGoalText').textContent=goalText;
 if($('sectorGoalState'))$('sectorGoalState').textContent=goalBadge;
 if($('sectorMeterFill'))$('sectorMeterFill').style.width=(visitedCount/4*100)+'%';
 if($('sectorMeter'))$('sectorMeter').setAttribute('aria-valuenow',String(visitedCount));
 if($('sectorMeterCaption'))$('sectorMeterCaption').textContent=`${visitedCount} secteur${visitedCount>1?'s':''} découvert${visitedCount>1?'s':''} sur 4`;
 if($('progressObjectiveHint'))$('progressObjectiveHint').textContent=goalText;
 document.querySelectorAll('[data-sector-card]').forEach(card=>{
  const i=Number(card.dataset.sectorCard),seen=i<=max,beacon=reg.outposts.includes(i);
  card.classList.toggle('unlocked',seen);
  card.classList.toggle('locked',!seen);
  card.classList.toggle('outpost',beacon);
  card.classList.toggle('current',i===max);
  const state=card.querySelector('[data-sector-state]');
  if(state)state.textContent=beacon?'✓ Découvert · balise activée':seen?'✓ Secteur découvert':'◇ Pas encore découvert';
 });
}
function merchantBuy(i){
 if(data.run)return;const w=ensureMerchant().stock[i];
 if(!w||w.sold||!Number.isFinite(w.price)||data.credits<w.price)return;
 if(!confirm(`Acheter ${w.name} (${w.rar}) pour ${w.price} crédits ?`))return;
 // Atomic state transition, persisted together: money, stock, item ownership.
 const item={id:uid(),name:w.name,rar:w.rar,dmg:w.dmg,rate:w.rate,purchasePrice:w.price,origin:"merchant"};
 data.credits-=w.price;data.stash.push(item);w.sold=true;
 persist();render();merchantRender();msg(`${item.name} acheté et placé dans la réserve.`);
}
function merchantSell(i){
 if(data.run)return;const w=data.stash[i];if(!w)return;
 if(w.id===data.insured){msg('Cet objet est assuré. Annule d’abord son assurance.');return}
 const price=salvagePrice(w);
 if(!confirm(`Vendre définitivement ${w.name} pour ${price} crédits ?`))return;
 data.stash.splice(i,1);data.credits+=price;persist();render();merchantRender();msg(`${w.name} vendu · +${price} crédits.`);
}

function upgrade(t){let lv=t==='hp'?data.hpLv:data.dmgLv,cost=4+lv*4;if(lv>=8||data.research<cost)return;data.research-=cost;if(t==='hp')data.hpLv++;else data.dmgLv++;persist();render()}
function insure(){if(!data.equipped||data.insured===data.equipped.id||data.credits<premium())return;data.credits-=premium();data.insured=data.equipped.id;persist();render();msg('Objet assuré pour la prochaine expédition.')}
// V56 : empreintes exactes des salles sur la mini-carte et la carte complete.
// La grille de navigation contient une salle logique par noeud ; chaque noeud
// represente ici ses 1, 2 ou 3 cellules, sans les confondre avec des salles voisines.
const ASH_MAP_COLORS=['#5d998d','#66bad1','#dc9d67','#ad8aca'];
function ashMapMarkup(run,mini=false){
 if(!run||!run.rooms||!run.rooms.some(z=>Number.isFinite(z.gx)&&Number.isFinite(z.gy)))return mini?'<span class="ash-map-unavailable">—</span>':'';
 const base=mini?39:39, sx=base,sy=base*1.06,subx=mini?18:13,suby=mini?19:13.7;
 const current=run.rooms[run.current],mapNodes=run.rooms.filter(z=>Number.isFinite(z.gx)&&Number.isFinite(z.gy));
 // 0.8.9.57: la mini-carte est un journal permanent, non une fenetre +/- 1 salle.
 // visited est conservé comme source de verité lors de la reprise d'anciennes sauvegardes.
 const visited=new Set(run.visited||[]),intel=new Set(run.intelRooms||[]);
 const known=z=>!!z.seen||visited.has(z.id)||intel.has(z.id)||z.id===run.current;
 const nodes=mapNodes.filter(known);
 const bounds=mini?nodes:mapNodes;
 const minx=Math.min(...bounds.map(z=>z.gx));
 const miny=Math.min(...bounds.map(z=>z.gy));
 const maxx=Math.max(...bounds.map(z=>z.gx));
 const maxy=Math.max(...bounds.map(z=>z.gy));
 const pad=mini?8:24,W=(maxx-minx)*sx+2*pad+2*subx,H=(maxy-miny)*sy+2*pad+2*suby;
 const center=z=>({x:(z.gx-minx)*sx+pad+subx/2,y:(z.gy-miny)*sy+pad+suby/2});
 const visibleIds=new Set(nodes.map(z=>z.id));
 const links=(run.edges||[]).filter(e=>e.length===2&&visibleIds.has(e[0])&&visibleIds.has(e[1])).map(e=>{
  const a=center(run.rooms[e[0]]),b=center(run.rooms[e[1]]);
  return `<line x1="${a.x}" y1="${a.y}" x2="${b.x}" y2="${b.y}" stroke="#648596" stroke-opacity=".7" stroke-width="${mini?2.8:4}" stroke-linecap="round"/>`;
 }).join('');
 const tiles=nodes.map(z=>{
  const px=(z.gx-minx)*sx+pad,py=(z.gy-miny)*sy+pad;
  const type=roomGeom(z).type, scanned=!z.seen&&!(run.visited||[]).includes(z.id)&&z.id!==run.current,here=z.id===run.current;
  const sector=Number.isFinite(z.sector)?z.sector:Math.min(3,Math.floor(z.id/13));
  const fill=scanned?'#344752':here?'#eab96e':ASH_MAP_COLORS[sector]||ASH_MAP_COLORS[0];
  const shape=type==='wide'?`M${px} ${py}h${subx*2}v${suby}h${-subx*2}z`:
   type==='tall'?`M${px} ${py}h${subx}v${suby*2}h${-subx}z`:
   type==='ell'?`M${px} ${py}h${subx*2}v${suby}h${-subx}v${suby}h${-subx}z`:
   `M${px} ${py}h${subx}v${suby}h${-subx}z`;
  const label=here?'●':scanned?'?':isBoss(z.id,run)?'B':isArena(z.id,run)?'A':isExit(z.id,run)?'E':z.kind==='outpost'?'P':'';
  const cx=px+subx/2,cy=py+suby/2;
  return `<g><path d="${shape}" fill="${fill}" fill-opacity="${scanned?.52:.96}" stroke="${here?'#fff3cc':'#a8cad3'}" stroke-width="${here?1.8:.9}" stroke-linejoin="round"/>${here?`<circle cx="${cx}" cy="${cy}" r="${mini?3.7:4.9}" fill="#11202a"/><circle cx="${cx}" cy="${cy}" r="${mini?2:2.7}" fill="#fff0ca"/>`:label?`<text x="${cx}" y="${cy+3}" fill="#f8f6ee" font-size="${mini?8:11}" text-anchor="middle" font-weight="900">${label}</text>`:''}</g>`;
 }).join('');
 if(mini)return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${W} ${H}" preserveAspectRatio="xMidYMid meet" focusable="false"><rect width="${W}" height="${H}" rx="6" fill="#0b1b25"/>${links}${tiles}</svg>`;
 return `<svg class="ash-map-full-svg" xmlns="http://www.w3.org/2000/svg" width="${Math.ceil(W)}" height="${Math.ceil(H)}" viewBox="0 0 ${W} ${H}" role="img" aria-label="Carte des salles découvertes, avec leurs formes réelles">${links}${tiles}</svg>`;
}
let ashLastMiniSignature='';
function ashRenderMiniMap(run){
 const target=$('ashMiniMap');if(!target)return;
 if(!run){target.innerHTML='';ashLastMiniSignature='';return}
 const knownVisited=new Set(run.visited||[]);
 const discovered=(run.rooms||[]).reduce((a,z)=>a+(z.seen||knownVisited.has(z.id)?1:0),0);
 const count=$('ashMiniMapCount');if(count)count.textContent=`${discovered}/50`;
 const scanned=(run.intelRooms||[]).length;
 // La carte est réactualisée à chaque changement de salle ou découverte.
 const signature=[run.current,discovered,scanned,(run.intelRooms||[]).join(',')].join('|');
 if(signature!==ashLastMiniSignature){target.innerHTML=ashMapMarkup(run,true);ashLastMiniSignature=signature;}
}
