 poly([[-10,-3],[10,-3],[11,6],[6,9],[-6,9],[-11,6]],'#5b4939');
 poly([[-10,-5],[-13,-13],[-9,-19],[9,-19],[13,-13],[10,-5],[8,4],[-8,4]],coat);
